import subprocess

PREDEFINED_GTF = "path/to/pre_defined.gtf"
PREDEFINED_FASTA = "path/to/pre_defined.fasta"

def append_files(gtf_file, fasta_file):
    pairs = ((PREDEFINED_GTF, gtf_file), (PREDEFINED_FASTA, fasta_file))
    for source, destination in pairs:
        with open(destination, "ab") as output_stream:
            process = subprocess.Popen(["cat", source], stdout=output_stream)
            if process.wait() != 0:
                raise RuntimeError("cat failed")

import sqlite3

def table_metadata(database_path, table_name):
    with sqlite3.connect(database_path) as connection:
        columns = connection.execute("SELECT * FROM pragma_table_info(?)", (table_name,)).fetchall()
        index_rows = connection.execute("SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = ?", (table_name,)).fetchall()
    return {"columns": columns, "indexes": [row[0] for row in index_rows]}
